const RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/;
function bad(s){ return !s || typeof s !== "string" || !RE.test(s); }
const i = $input.first().json;
const node = (i.node && String(i.node).trim()) || "";
if (node && bad(node)) return [{json: {blocked: true, ok: false, detail: "invalid node name"}}];
return [{json: {url: node ? `https://kubernetes.default.svc/api/v1/nodes/${node}` : "https://kubernetes.default.svc/api/v1/nodes", node}}];

const r = $input.first().json;
if (r.blocked) return [{json: r}];
if (r.statusCode >= 400) return [{json: {blocked: true, ok: false, detail: `K8s API ${r.statusCode}: ${JSON.stringify(r.body?.message || r.body).slice(0,200)}`}}];
return [{json: {url: "https://kubernetes.default.svc/apis/metrics.k8s.io/v1beta1/nodes"}}];

const m = $input.first().json;
if (m.blocked) return [{json: {ok: false, detail: m.detail}}];
const n = $('K8s GET nodes').first().json;
const items = n.body.items || (n.body.kind === "Node" ? [n.body] : []);
const usage = {}; (m.statusCode < 400 ? (m.body.items || []) : []).forEach(x => usage[x.metadata.name] = x.usage);
const toMi = (q) => { if (!q) return null; const s = String(q); if (s.endsWith("Ki")) return Math.round(parseFloat(s)/1024); if (s.endsWith("Mi")) return Math.round(parseFloat(s)); if (s.endsWith("Gi")) return Math.round(parseFloat(s)*1024); return Math.round(parseFloat(s)/1048576); };
const toM = (q) => { if (!q) return null; const s = String(q); if (s.endsWith("n")) return Math.round(parseFloat(s)/1e6); if (s.endsWith("u")) return Math.round(parseFloat(s)/1e3); if (s.endsWith("m")) return Math.round(parseFloat(s)); return Math.round(parseFloat(s)*1000); };
const nodes = items.map(nd => {
  const u = usage[nd.metadata.name] || {};
  const allocMi = toMi(nd.status.allocatable?.memory), usedMi = toMi(u.memory);
  const allocM = toM(nd.status.allocatable?.cpu), usedM = toM(u.cpu);
  const cond = (nd.status.conditions||[]).filter(c => c.type === "Ready" ? c.status !== "True" : c.status === "True").map(c => `${c.type}=${c.status} (${c.reason||""})`);
  return {name: nd.metadata.name, roles: Object.keys(nd.metadata.labels||{}).filter(k => k.startsWith("node-role.kubernetes.io/")).map(k => k.split("/")[1]),
    ready: (nd.status.conditions||[]).some(c => c.type === "Ready" && c.status === "True"), problemConditions: cond,
    memory: usedMi !== null && allocMi ? `${usedMi} Mi of ${allocMi} Mi allocatable (${Math.round(usedMi/allocMi*100)}%)` : "n/a",
    cpu: usedM !== null && allocM ? `${usedM}m of ${allocM}m (${Math.round(usedM/allocM*100)}%)` : "n/a",
    kernel: nd.status.nodeInfo?.kernelVersion, kubelet: nd.status.nodeInfo?.kubeletVersion, arch: nd.status.nodeInfo?.architecture,
    unschedulable: !!nd.spec.unschedulable, taints: (nd.spec.taints||[]).map(t => `${t.key}=${t.value||""}:${t.effect}`)};
});
return [{json: {ok: true, count: nodes.length, nodes, hint: "Node memory % is the kubelet/metrics-server view (working set). Use get_top_pods with node=<name> to see which pods consume it."}}];
